import numpy as np

def step(l,y,s):
    V=np.array([l**j*y for j in range(s+1)]).T
    Q,R=np.linalg.qr(V)
    z=Q[:,-1]
    if np.dot(z,l**s*y)<0:z=-z
    return z

rng=np.random.default_rng(8)
for s in [2,3,4]:
 for n in [2*s,2*s+1,3*s]:
  l=np.sort(rng.uniform(-1,1,n)); y=rng.normal(size=n);y/=np.linalg.norm(y)
  hist=[]
  for k in range(40000):
   y=step(l,y,s)
   if k%2000==0:hist.append(y.copy())
  print(s,n,l, np.linalg.norm(hist[-1]-hist[-2]),np.round(y*y,5))

